<?php $steps=$props['steps'];$columns=count($steps);$cols=$columns===6?'md:grid-cols-3 lg:grid-cols-6':($columns===3?'md:grid-cols-3':'md:grid-cols-2 lg:grid-cols-4'); ?>
<div class="grid grid-cols-1 <?= $cols ?> gap-px bg-border border border-border"><?php foreach($steps as $i=>$step): ?><div class="bg-background p-6 md:p-8 flex flex-col"><div class="flex items-center justify-between"><span class="mono-label-accent">Fase <?= e($step['step']) ?></span><span class="font-mono text-[11px] text-muted-foreground/60"><?= e($step['step']) ?>/<?= sprintf('%02d',$columns) ?></span></div><h3 class="mt-4 font-heading font-semibold text-lg"><?= e($step['title']) ?></h3><p class="mt-2 text-sm text-muted-foreground leading-relaxed"><?= e($step['text']) ?></p></div><?php endforeach; ?></div>
